const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,TARGET_HASH=process.env.TARGET_HASH,TARGET_BYTES=Number(process.env.TARGET_BYTES);const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerValue:l.value,winnerImportant:l.important,winnerLine:l.line});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`]);assert(cp.execSync(`git rev-parse ${PARENT}:${TARGET}`,{encoding:'utf8'}).trim()===PARENT_BLOB,'parent blob drift');const src=parent.toString('utf8'),p=parse(src);assert(p.declarations.length===209&&p.dead.length===6,`parent parse drift ${p.declarations.length}/${p.dead.length}`);const selector='html.chat-room-mobile-open body:is([data-page="mensagens"], [data-page="comunidade-interna"]) :is(.messages-composer__field, .community-room-composer__field)';const expected=[['min-inline-size','0'],['min-width','0'],['inline-size','100%'],['width','100%'],['block-size','40px'],['height','40px']];for(let i=0;i<expected.length;i++){const d=p.dead[i],[prop,val]=expected[i];assert(d.selector===selector&&d.property===prop&&d.value===val&&!d.important&&d.context==='@media (max-width: 560px)'&&d.winnerValue===val&&!d.winnerImportant&&d.winnerLine>d.line,`parent dead row ${i} drift`);}const finalNewline=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line))lines.splice(d.line-1,1);const rebuilt=Buffer.from(lines.join('\n')+(finalNewline?'\n':''));const actual=fs.readFileSync(TARGET);assert(rebuilt.equals(actual),'independent candidate bytes differ from permanent');const parsed=parse(actual.toString('utf8'));assert(parsed.declarations.length===203&&parsed.dead.length===0,`permanent parse drift ${parsed.declarations.length}/${parsed.dead.length}`);const hash=crypto.createHash('sha256').update(actual).digest('hex');assert(hash===TARGET_HASH,`hash drift ${hash}`);assert(actual.length===TARGET_BYTES,`bytes drift ${actual.length}`);assert(cp.execSync(`git hash-object ${TARGET}`,{encoding:'utf8'}).trim()===TARGET_BLOB,'target blob drift');console.log(`EXACT BYTE IDENTITY PASS|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${actual.length}|decl=209->203|dead=6->0|staticCascadeRows=6|identicalWinners=6`);
